interface PaymentProcessor {
    // Abstract method - must be implemented
    boolean processPayment(double amount);

    // Default method - inherited by all implementations
    default String formatReceipt(double amount) {
        return String.format("Payment of $%.2f processed successfully", amount);
    }

    default void logTransaction(double amount) {
        System.out.println("Transaction: " + amount);
    }
}

class CreditCardProcessor implements PaymentProcessor {
    @Override
    public boolean processPayment(double amount) {
        // Custom payment logic
        return amount > 0 && amount < 10000;
    }
    // Inherits formatReceipt and logTransaction automatically
}

class BitcoinProcessor implements PaymentProcessor {
    @Override
    public boolean processPayment(double amount) {
        return amount > 0;
    }

    @Override
    public String formatReceipt(double amount) {
        // Custom override for crypto
        return "Bitcoin payment: " + amount + " BTC";
    }
}

interface UserRepository {
    List<User> findAll();
    Optional<User> findById(Long id);

    // Static factory method - called as UserRepository.createInMemory()
    static UserRepository createInMemory() {
        return new InMemoryUserRepository();
    }

    static UserRepository createDatabase(String url) {
        return new DatabaseUserRepository(url);
    }

    // Static utility method
    static boolean isValidUserId(Long id) {
        return id != null && id > 0;
    }
}

class InMemoryUserRepository implements UserRepository {
    private final List<User> users = new ArrayList<>();

    @Override
    public List<User> findAll() {
        return List.copyOf(users);
    }

    @Override
    public Optional<User> findById(Long id) {
        return users.stream()
            .filter(u -> u.id().equals(id))
            .findFirst();
    }
}

// Usage
var repo = UserRepository.createInMemory();
if (UserRepository.isValidUserId(userId)) {
    repo.findById(userId);
}

interface Notifier {
    default void send(String message) {
        System.out.println("Notifier: " + message);
    }
}

interface Logger {
    default void send(String message) {
        System.out.println("Logger: " + message);
    }
}

// This class MUST resolve the conflict
class AlertSystem implements Notifier, Logger {

    @Override
    public void send(String message) {
        // Option 1: Choose one parent's implementation
        Notifier.super.send(message);

        // Option 2: Combine both behaviors
        // Notifier.super.send(message);
        // Logger.super.send(message);

        // Option 3: Provide completely new implementation
        // System.out.println("Alert: " + message);
    }
}

// Usage
var alert = new AlertSystem();
alert.send("System overload");  // Output: Notifier: System overload

// Without the override, this class won't compile:
// error: class AlertSystem inherits unrelated defaults for send(String)

