public class DefaultVsAbstractMethod {
    interface Payment {
        void pay(double amount);              // abstract: every impl MUST define it
        default void refund(double amount) {  // default: optional shared behavior
            System.out.println("Refunding " + amount);
        }
    }

    static class CardPayment implements Payment {
        public void pay(double amount) {      // required
            System.out.println("Charging card " + amount);
        }
        // refund() is inherited from the default method
    }

    public static void main(String[] args) {
        Payment p = new CardPayment();
        p.pay(100);    // Charging card 100.0
        p.refund(40);  // Refunding 40.0
    }
}
```

